#!/usr/bin/env python3
"""Package the frame-specific research: no material textures, shader changes or fabricated trailer frames."""
from pathlib import Path
import argparse,base64,hashlib,html,json,os,sys,zipfile
local=Path('/workspace/test-tools/python')
if local.exists():sys.path.insert(0,str(local))
import markdown2
parser=argparse.ArgumentParser();parser.add_argument('--evidence',type=Path,required=True);a=parser.parse_args();w=a.evidence;root=Path(__file__).resolve().parents[1];esc=html.escape
os.environ.setdefault('MPLCONFIGDIR',str(w/'matplotlib-cache'))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
study=json.loads((w/'reference-material-study.json').read_text());materials=study['materials'];names=['Cut log','Bark','Crafting top','Blue wool','Ender chest'];media={};figures=[]
plt.rcParams.update({'figure.facecolor':'#102027','axes.facecolor':'#102027','axes.edgecolor':'#45616a','text.color':'#e5ece9','axes.labelcolor':'#c5d5d5','xtick.color':'#c5d5d5','ytick.color':'#c5d5d5','font.size':11,'savefig.facecolor':'#102027'})
fig,ax=plt.subplots(figsize=(12,5));values=[m['luminanceHeightCorrelation'] for m in materials];bars=ax.bar(names,values,color=['#edb57e' if v<0 else '#72d5c4' for v in values],width=.6);ax.axhline(0,color='#a0b8bd',lw=1);ax.set_ylim(-1.12,1.15);ax.set_ylabel('Pearson correlation with authored height');ax.set_title('The same brightness rule does not fit every surface',loc='left',pad=18)
for b,v in zip(bars,values):ax.text(b.get_x()+b.get_width()/2,v+(.06 if v>=0 else -.06),f'{v:+.3f}',ha='center',va='bottom' if v>=0 else 'top',fontsize=12)
ax.spines[['top','right']].set_visible(False);fig.text(.08,.025,'Measured from opaque texels in the public AVPBR R5 demo; not the verified trailer revision.',fontsize=9,color='#a8bdc1');fig.tight_layout(rect=(0,.06,1,1));p=w/'height-polarity.png';fig.savefig(p,dpi=150);plt.close(fig)
fig,ax=plt.subplots(figsize=(12,5));x=list(range(5));ax.bar([i-.17 for i in x],[m['constantColorCellFraction']*100 for m in materials],width=.34,label='Groups with constant colour',color='#eab17d');ax.bar([i+.17 for i in x],[m['varyingNormalCellFraction']*100 for m in materials],width=.34,label='Groups with varying fine normals',color='#72d5c4');ax.set_xticks(x,names);ax.set_ylim(0,123);ax.set_ylabel('Percent of occupied native-pixel groups');ax.set_title('Blocky colour art can contain much finer surface shaping',loc='left',pad=18);ax.legend(loc='upper left',frameon=False,fontsize=10,ncol=2);ax.spines[['top','right']].set_visible(False);fig.text(.08,.025,'An 8×8 group corresponds to one vanilla colour texel. Transparent skin space is excluded.',fontsize=9,color='#a8bdc1');fig.tight_layout(rect=(0,.06,1,1));p=w/'fine-normal-detail.png';fig.savefig(p,dpi=150);plt.close(fig)
def card(name,data,title,caption,source=''):
 assert name==Path(name).name;media['media/'+name]=data;figures.append({'file':name,'sha256':hashlib.sha256(data).hexdigest(),'title':title,'scope':caption})
 return '<figure><button class="zoom" aria-label="Enlarge '+esc(title,quote=True)+'"><img loading="lazy" src="media/'+name+'" alt="'+esc(title,quote=True)+'"></button><figcaption><strong>'+esc(title)+'</strong><p>'+esc(caption)+'</p>'+source+'</figcaption></figure>'
charts=''.join(card(n,(w/n).read_bytes(),t,c) for n,t,c in [('height-polarity.png','Measured height polarity','Cut wood and bark need opposite treatment. The Ender-chest height is almost unrelated to brightness.'),('fine-normal-detail.png','Measured fine normal detail','Fine shaping exists within flat colour groups. These are data plots, not rendered examples of a new Aurum feature.')])
gallery=json.loads((w/'gallery-sources.json').read_text());refs=[]
for g in gallery:
 data=(w/g['file']).read_bytes();assert hashlib.sha256(data).hexdigest()==g['sha256'];refs.append(card(g['file'],data,'Supporting creator render · '+g['title'],'AVPBR creator gallery, listed as R7 B2 / @lovelyrune. A separate camera and version from the supplied screenshots and R5 audit; not an Aurum render.','<small>AVPBR Retextured / JoaquiX · gallery credit @lovelyrune · <a href="'+esc(g['url'],quote=True)+'">source image</a></small>'))
baselines=[];baseline_states=[]
old=root/'../scratch/excal-relief-research/captures'
for name in ['vanilla-close','excal-close']:
 p=old/(name+'.png');d=json.loads(p.with_suffix('.json').read_text());data=p.read_bytes();assert hashlib.sha256(data).hexdigest()==d['sha256'] and not d['snapshot']['config']['labPbr'];baseline_states.append(d);baselines.append(card(p.name,data,('Vanilla' if name.startswith('vanilla') else 'Excalibur')+' · existing Aurum baseline','Previously captured unmodified 0.6.2-alpha.1 renderer, LabPBR off, software OpenGL. This is a baseline from the earlier study, not a new implementation or a matched trailer shot.'))
sourceurls=[{'title':'AVPBR project and recommendations','url':'https://modrinth.com/resourcepack/avpbr-retextured'},{'title':'NostalgiaVX public description','url':'https://rre36.com/nostalgiavx'},{'title':'LabPBR material standard','url':'https://shaderlabs.org/wiki/LabPBR_Material_Standard'},{'title':'Parallax explanation','url':'https://learnopengl.com/Advanced-Lighting/Parallax-Mapping'}]
sourcepaths=['src/main/java/dev/impeccable/aurum/bake/AtlasBaker.java','src/main/resources/assets/aurum/shaders/include/pbr.glsl','src/main/resources/assets/aurum/shaders/include/model_light.glsl','src/main/resources/assets/aurum/shaders/include/surface_light.glsl']
evidence={'date':'2026-10-26','scope':'Research only; no renderer changes or new mod release','targets':[{'frame':1,'source':'User-supplied still in conversation','subject':'Wood cabin and Ender chest'},{'frame':2,'source':'User-supplied still in conversation','subject':'Cut log and bark'},{'frame':3,'source':'User-supplied still in conversation','subject':'Crafting table and coloured floor'}],'referenceStudy':study,'excalTargetCases':json.loads((w/'excal-target-cases.json').read_text()),'sourceReferences':sourceurls,'sourceHashes':{n:hashlib.sha256((root/n).read_bytes()).hexdigest() for n in sourcepaths},'figures':figures,'supportingCreatorImages':gallery,'oldBaselineStates':baseline_states,'limits':['The supplied stills are visually analysed; no full trailer playback is claimed.','No new surface-depth implementation or target-GPU benchmark.','The three in-chat stills are described; supporting gallery images are separately attributed and not presented as those frames.','No copyrighted normal/height/specular texture files are redistributed.']}
(root/'docs/research/surface-depth-reference-evidence.json').write_text(json.dumps(evidence,indent=2)+'\n')
css='''*{box-sizing:border-box}html{background:#0c1518;color:#e5ece9;color-scheme:dark;font:17px/1.65 system-ui,sans-serif}body{margin:0;overflow-wrap:anywhere}header,main{max-width:1300px;margin:auto;padding:30px 28px}header{padding-top:56px}h1{font:clamp(38px,5vw,68px)/1.12 Georgia,serif;max-width:980px}h2{font:30px/1.3 Georgia,serif;margin:42px 0 18px}h3{font-size:21px;color:#efb87d}a{color:#9de5e2}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.15em;color:#efb87d;text-transform:uppercase}.lead{font-size:21px;max-width:1010px}.notice{padding:18px 22px;border-left:4px solid #eeb87c;background:#203037}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0;background:#14242a;border:1px solid #355059;min-width:0}figure img{width:100%;display:block}figcaption{padding:18px}figcaption p{font-size:14px;color:#bdcdd0;margin:8px 0}small{font-size:12px;color:#efb87d}.zoom{display:block;padding:0;border:0;background:transparent;width:100%;cursor:zoom-in}.table-scroll{overflow:auto}table{display:block;overflow:auto;border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px;text-align:left;vertical-align:top;border-bottom:1px solid #355059}th{background:#203037}code{font-size:.86em;background:#203037;padding:2px 5px}nav{display:flex;flex-wrap:wrap;gap:18px}.demo{background:#14242a;border:1px solid #355059;padding:20px}.controls{display:flex;flex-wrap:wrap;gap:20px}.controls label{display:grid;gap:6px;min-width:160px}canvas{display:block;width:100%;height:auto;margin-top:16px;background:#102027}dialog{background:#0c1518;border:1px solid #75969b;padding:12px;max-width:96vw;max-height:96vh}dialog img{max-width:90vw;max-height:80vh}dialog::backdrop{background:#000c}dialog button{display:block;margin:0 0 10px auto;padding:8px 18px;cursor:pointer}@media(max-width:700px){header,main{padding:24px 16px}.gallery{grid-template-columns:1fr}.lead{font-size:18px}}'''
header='''<header><p class="eyebrow">Aurum · reference-led material research · 26 October 2026</p><h1>Surface depth from ordinary resource packs.</h1><p class="lead">Recessed log rings, shaped block pixels and crisp highlights: how to pursue the depth in your three screenshots, with Excalibur and LabPBR disabled.</p><p class="notice"><strong>Feasible as a general effect; exact automatic reconstruction is not guaranteed.</strong> Generate material data inside Aurum, handle terrain and chest skins, and keep the result stable in motion. This is research, with measured reference materials and existing baselines—not a new visual build.</p><nav><a href="#target">Three target scenes</a><a href="#measurements">Measured material data</a><a href="#mechanism">Depth demonstration</a><a href="#plan">Full proposal</a><a href="evidence.json">Evidence JSON</a></nav></header>'''
scenes='''<h2 id="target">The targets are these three situations</h2><table><thead><tr><th>Supplied shot</th><th>Depth to preserve</th><th>Coverage that must be tested</th></tr></thead><tbody><tr><td>Wood cabin / Ender chest</td><td>Wood and floor relief; clean lid and latch forms under warm local light</td><td>Terrain plus block-entity skins, lid motion and local light directions</td></tr><tr><td>Cut log</td><td>Stepped rings, bark channels, fine bright edges and recesses</td><td>Different height polarity on end grain and bark; moving/grazing camera</td></tr><tr><td>Crafting table / coloured floor</td><td>Selective recessed grid, side trim and fine fabric grain</td><td>Top/side charts, shallow floor relief and stable specular filtering</td></tr></tbody></table><p>The supplied images in chat are the direct visual targets. The creator renders below are additional material examples, not exported frames from that video.</p>'''
demo='''<h2 id="mechanism">Why a normal map and actual relief behave differently</h2><div class="demo"><div class="controls"><label>Surface mode<select id="mode"><option value="flat">Flat colour</option><option value="normal">Normal-map shaping</option><option value="relief" selected>Height-field relief</option></select></label><label>Depth <input id="depth" type="range" min="0" max="100" value="65"></label><label>View angle <input id="angle" type="range" min="10" max="65" value="35"></label></div><canvas id="section" width="1100" height="350" aria-label="Interactive height-field cross section"></canvas><p id="demotext"></p><small>Explanatory cross-section with constructed data. This is not Minecraft footage or a prototype quality/performance result. The marker shows the first hit of the illustrated view ray.</small></div>'''
analysis=markdown2.markdown((root/'docs/research/SURFACE_DEPTH_FROM_REFERENCE_FRAMES.md').read_text().split('\n',1)[1],extras=['tables','fenced-code-blocks'])
body=header+'<main>'+scenes+'<div class="gallery">'+''.join(refs)+'</div><h2 id="measurements">Reference material measurements</h2><p>Official public R5 demo, distinct from the unverified older video revision. Only opaque colour texels are included. No raw material maps are distributed.</p><div class="gallery">'+charts+'</div>'+demo+'<h2>Existing Aurum · unchanged baseline</h2><div class="gallery">'+''.join(baselines)+'</div><section id="plan">'+analysis+'</section></main>'
js='''const d=document.querySelector('dialog');document.querySelectorAll('.zoom').forEach(b=>b.onclick=()=>{d.querySelector('img').src=b.querySelector('img').src;d.showModal()});d.querySelector('button').onclick=()=>d.close();const cv=document.getElementById('section'),cx=cv.getContext('2d'),md=document.getElementById('mode'),dp=document.getElementById('depth'),an=document.getElementById('angle');function draw(){const heights=[.28,.28,.6,.6,.24,.24,.8,.8,.38,.38,.68,.68],scale=+dp.value/100,relief=md.value==='relief',bw=65,start=120,base=290,hs=170;cx.fillStyle='#102027';cx.fillRect(0,0,1100,350);for(let i=0;i<heights.length;i++){const h=relief?heights[i]*scale:0;cx.fillStyle=i%4<2?'#ad7851':'#d0a16a';cx.fillRect(start+i*bw,base-h*hs,bw,40+h*hs);cx.strokeStyle='#ead3b1';cx.lineWidth=2;cx.beginPath();cx.moveTo(start+i*bw,base-h*hs);cx.lineTo(start+(i+1)*bw,base-h*hs);cx.stroke();if(md.value==='normal'){const nx=(heights[(i+1)%heights.length]-heights[(i+heights.length-1)%heights.length])*scale;cx.strokeStyle='#72d5c4';cx.beginPath();cx.moveTo(start+(i+.5)*bw,base);cx.lineTo(start+(i+.5)*bw+nx*45,base-35);cx.stroke();}}const theta=+an.value*Math.PI/180,origin={x:420+Math.tan(theta)*200,y:35},dx=-Math.sin(theta),dy=Math.cos(theta);let hit=null;for(let t=0;t<650;t+=.25){const x=origin.x+dx*t,y=origin.y+dy*t,i=Math.floor((x-start)/bw);if(i>=0&&i<heights.length&&y>=base-(relief?heights[i]*scale*hs:0)){hit={x,y};break;}}cx.strokeStyle='#f1d177';cx.lineWidth=3;cx.beginPath();cx.moveTo(origin.x,origin.y);cx.lineTo(hit?hit.x:origin.x+dx*420,hit?hit.y:origin.y+dy*420);cx.stroke();if(hit){cx.fillStyle='#fff0ba';cx.beginPath();cx.arc(hit.x,hit.y,7,0,Math.PI*2);cx.fill();}cx.fillStyle='#d5e4e3';cx.font='18px system-ui';cx.fillText('View ray',origin.x+16,origin.y+5);document.getElementById('demotext').textContent=md.value==='normal'?'Normals change light response while the illustrated surface remains flat.':relief?'Depth changes the first visible intersection. A view march can shade exposed side walls and hide recesses.':'Colour alone does not provide view-dependent depth.';}[md,dp,an].forEach(x=>x.addEventListener('input',draw));draw();'''
offline='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aurum — surface depth research</title><style>'+css+'</style>'+body+'<dialog><button>Close</button><img alt="Enlarged source figure"></dialog><script>'+js+'</script></html>'
standalone=offline
for name,data in media.items():standalone=standalone.replace('src="'+name+'"','src="data:image/png;base64,'+base64.b64encode(data).decode()+'"')
standalone=standalone.replace('href="evidence.json"','href="https://raw.githubusercontent.com/atobouh/aurum/codex/docs/research/surface-depth-reference-evidence.json"');(root/'docs/reports/aurum-surface-depth-research.html').write_text(standalone)
prefix='Aurum-surface-depth-research/';bundle=root/'dist/aurum-surface-depth-research.zip'
with zipfile.ZipFile(bundle,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 z.writestr(prefix+'index.html',offline);z.writestr(prefix+'evidence.json',json.dumps(evidence,indent=2)+'\n');z.writestr(prefix+'research.md',(root/'docs/research/SURFACE_DEPTH_FROM_REFERENCE_FRAMES.md').read_bytes())
 for n,data in media.items():z.writestr(prefix+n,data)
 z.writestr(prefix+'README.txt','Extract All, then open Aurum-surface-depth-research/index.html in a browser. Keep media beside index.html. All six figures and the interactive schematic work offline.\n\nThe three supplied stills in chat are analysed in the text. Creator gallery images are labelled as supporting references, not those video frames. Charts are measured statistics. Earlier Minecraft baseline captures are unchanged. No new renderer or mod JAR. No raw copyrighted material textures are included.\n')
print('Created',bundle,len(media),'figures; bytes',bundle.stat().st_size)
